import{_ as a,o as t,c as r,a5 as n}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"Part IV: Practice and Recovery","description":"Bring learning and change into real schedules, using first-week practice, capacity design, and returnable rhythm so action can survive busyness, interruption, and low seasons.","frontmatter":{"title":"Part IV: Practice and Recovery","description":"Bring learning and change into real schedules, using first-week practice, capacity design, and returnable rhythm so action can survive busyness, interruption, and low seasons.","updated":"2026-09-02T00:00:00.000Z"},"headers":[],"relativePath":"en/threads/part-4/practice-and-recovery.md","filePath":"en/threads/part-4/practice-and-recovery.md","lastUpdated":1788307200000}'),i={name:"en/threads/part-4/practice-and-recovery.md"};function o(s,e,d,l,h,c){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="part-iv-practice-and-recovery" tabindex="-1">Part IV: Practice and Recovery <a class="header-anchor" href="#part-iv-practice-and-recovery" aria-label="Permalink to &quot;Part IV: Practice and Recovery&quot;">​</a></h1><p>A plan is almost always tidier on paper than it is in life.</p><p>Paper has no unexpected call, sleepless night, person who needs care, or afternoon when strength suddenly disappears. It knows only goals, dates, and a line that appears to keep moving forward. Real change must enter these untidy days before we know whether it can stand.</p><p>This part adds no larger ambition. It places the abilities, stories, tools, and evidence from earlier parts inside one week, one day, and one interruption. We will observe which conditions make action easier to begin, which costs are being hidden, how weight changes when capacity falls, and how to know where to return after stopping.</p><p>A reliable system is not one that never breaks. It is one that keeps a way back after the break without requiring you to humiliate yourself first.</p><h2 id="questions-for-this-part" tabindex="-1">Questions for This Part <a class="header-anchor" href="#questions-for-this-part" aria-label="Permalink to &quot;Questions for This Part&quot;">​</a></h2><ul><li>How can a first week leave a baseline, feedback, delayed retest, and transfer instead of only a streak?</li><li>How can full, compressed, and recovery days carry different weights?</li><li>How do time, energy, relationships, and the body enter one budget?</li><li>What genuinely compounds, and which repetitions only accumulate exhaustion?</li><li>After interruption, how can one small action restore rhythm without compensatory depletion?</li><li>When the learner is not yet an adult, how do learner, guardian, teacher, and AI divide responsibility without removing agency?</li></ul><p>Recovery here does not mean returning to productivity as quickly as possible. Safety, food, sleep, asking for help, and basic care may be the most important work of the day.</p><h2 id="reading-path" tabindex="-1">Reading Path <a class="header-anchor" href="#reading-path" aria-label="Permalink to &quot;Reading Path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Chapters</th><th>What to leave behind</th></tr></thead><tbody><tr><td>Finish one week</td><td><a href="./week-1">Practice: Finish the First Week</a></td><td>Baseline, seven-day evidence chain, and weekend decision</td></tr><tr><td>Learn together as a family (when relevant)</td><td><a href="./family-learning">Family Learning: Return Ownership of Growth to the Learner</a></td><td>One learner-defined task, role boundaries, and a fourteen-day shared agreement</td></tr><tr><td>Place it inside a day</td><td><a href="./daily-system">Daily System</a></td><td>Three capacity modes, an environment entry point, and relationship boundaries</td></tr><tr><td>Give it to time</td><td><a href="./rhythm-and-compounding">Rhythm</a></td><td>Repeatable action, return protocol, and review date</td></tr></tbody></table><p>Do not rebuild sleep, learning, exercise, work, and every relationship in the same week. Choose one main question. A system that requires five simultaneous reforms before it works is not ready for real life.</p><h2 id="what-to-carry-forward" tabindex="-1">What to Carry Forward <a class="header-anchor" href="#what-to-carry-forward" aria-label="Permalink to &quot;What to Carry Forward&quot;">​</a></h2><p>At the end of this part, leave:</p><ol><li>One <a href="./../../templates/rhythm-ledger">Rhythm Ledger</a> recording capacity, minimum action, and resistance; when supporting a young learner, also keep a <a href="./../../templates/family-learning-agreement">Family Learning Agreement</a>;</li><li>A record of returning after a real interruption;</li><li>One design to continue and one demand explicitly removed;</li><li>A protected window, a boundary you can state, and a person you can contact when needed.</li></ol><p>Rising numbers are not the only outcome. Noticing exhaustion earlier, repaying fewer interruptions with lost sleep, asking for help sooner, and knowing what should not continue are also evidence that a system is becoming reliable.</p><h2 id="enter-the-work" tabindex="-1">Enter the Work <a class="header-anchor" href="#enter-the-work" aria-label="Permalink to &quot;Enter the Work&quot;">​</a></h2><p>Do not design an ideal year yet. Reduce the future to seven days and let one question meet a real schedule, different capacities, and one weekend review.</p><p>One week cannot define you. It can still tell you whether the next week should become lighter or clearer.</p>',18)])])}const y=a(i,[["render",o]]);export{u as __pageData,y as default};
